import sys

class BIT:

	def __init__(self, n):
		self.n = n
		self.tree = [0] * n

	def _F(self, i):
		return i & i + 1

	def _getSum(self, r):
		result = 0
		while r >= 0:
			result += self.tree[r]
			r = self._F(r) - 1
		return result

	def getSum(self, l, r):
		return self._getSum(r) - self._getSum(l - 1)

	def _H(self, i):
		return i | i + 1

	def add(self, i, value):
		while i < self.n:
			self.tree[i] += value
			i = self._H(i)
reader = (line.rstrip() for line in sys.stdin)
input = reader.__next__
n = int(input())
segm = [0] * (2 * n + 1)
edge = [0] * (2 * n + 1)
for i in range(n):
	(l, r) = map(int, input().split())
	segm[l] = segm[r] = i
	edge[l] = edge[r] = r
opened = BIT(2 * n + 1)
g = [[] for _ in range(n)]
ctr = 0
for e in range(1, 2 * n + 1):
	r = edge[e]
	if e == r:
		opened.add(e, -1)
	else:
		opened.add(r, 1)
		add = opened.getSum(0, r - 1)
		ctr += add
		if ctr > n - 1:
			print('NO')
			sys.exit()
		for k in range(add):
			L = 0
			R = r - 1
			while L + 1 < R:
				m = L + R >> 1
				if opened.getSum(0, m) > k:
					R = m
				else:
					L = m
			i = segm[e]
			j = segm[R]
			g[i].append(j)
			g[j].append(i)
visited = [False] * n
stack = [0]
while stack:
	v = stack.pop()
	if not visited[v]:
		visited[v] = True
		for to in g[v]:
			stack.append(to)
print('YES' if all(visited) else 'NO')
